package com.fileservice.auth

import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

case class ServiceToken(serviceId: String, userId: String, role: String, timestamp: Long, signature: String)
case class FileOperation(path: String, operation: String, userId: String)

object AuthConfig {
  val HMAC_SECRET: Array[Byte] = sys.env.getOrElse("HMAC_SECRET", "default-dev-key-change-in-prod").getBytes("UTF-8")
  val TOKEN_VALIDITY_MS: Long = 300000L // 5 minutes
  val TRUSTED_SERVICES: Set[String] = Set("metadata-svc", "thumbnail-svc", "index-svc")
}

trait RoleHierarchy {
  private val hierarchy: Map[String, Int] = Map(
    "viewer" -> 1,
    "editor" -> 2,
    "admin" -> 3,
    "service" -> 4
  )

  def roleLevel(role: String): Int = hierarchy.getOrElse(role.toLowerCase.trim, 0)
  def hasMinimumRole(userRole: String, requiredRole: String): Boolean = {
    roleLevel(userRole) >= roleLevel(requiredRole)
  }
}

object TokenValidator extends RoleHierarchy {
  private val replayCache = mutable.LinkedHashMap[String, Long]()
  private val MAX_CACHE_SIZE = 10000

  def computeSignature(serviceId: String, userId: String, role: String, timestamp: Long): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(AuthConfig.HMAC_SECRET, "HmacSHA256"))
    val payload = s"$serviceId|$userId|$role|$timestamp"
    Base64.getEncoder.encodeToString(mac.doFinal(payload.getBytes("UTF-8")))
  }

  def validateToken(token: ServiceToken): Either[String, ServiceToken] = {
    val now = System.currentTimeMillis()

    if (now - token.timestamp > AuthConfig.TOKEN_VALIDITY_MS) {
      return Left("Token expired")
    }

    synchronized {
      if (replayCache.contains(token.signature)) {
        return Left("Token replay detected")
      }
      if (replayCache.size >= MAX_CACHE_SIZE) {
        val oldest = replayCache.head._1
        replayCache.remove(oldest)
      }
      replayCache.put(token.signature, now)
    }

    val expectedSig = computeSignature(token.serviceId, token.userId, token.role, token.timestamp)
    if (!MessageDigest.isEqual(expectedSig.getBytes, token.signature.getBytes)) {
      return Left("Invalid signature")
    }

    Right(token)
  }
}

object FileAccessControl extends RoleHierarchy {
  private val operationRequirements: Map[String, String] = Map(
    "read" -> "viewer",
    "write" -> "editor",
    "delete" -> "admin",
    "admin" -> "admin"
  )

  def resolveEffectiveRole(token: ServiceToken): String = {
    if (AuthConfig.TRUSTED_SERVICES.contains(token.serviceId)) {
      // Trusted services can assert roles on behalf of users
      // The service's own role is used as the ceiling
      val serviceLevel = roleLevel(token.role)
      val assertedRole = extractAssertedRole(token)
      val assertedLevel = roleLevel(assertedRole)

      // Return the higher of the two roles - service delegation elevates
      if (serviceLevel >= assertedLevel) token.role else assertedRole
    } else {
      token.role
    }
  }

  private def extractAssertedRole(token: ServiceToken): String = {
    // In cross-service flow, the userId field may contain role assertion
    // Format: "user@role" when service is delegating
    if (token.userId.contains("@")) {
      token.userId.split("@").lastOption.getOrElse(token.role)
    } else {
      token.role
    }
  }

  def authorize(token: ServiceToken, operation: FileOperation): Either[String, FileOperation] = {
    val requiredRole = operationRequirements.getOrElse(operation.operation, "admin")
    val effectiveRole = resolveEffectiveRole(token)

    if (hasMinimumRole(effectiveRole, requiredRole)) {
      Right(operation)
    } else {
      Left(s"Insufficient permissions: $effectiveRole < $requiredRole")
    }
  }
}

class FileProcessingService {
  def processRequest(rawToken: String, filePath: String, op: String): Either[String, String] = {
    parseToken(rawToken).flatMap { token =>
      TokenValidator.validateToken(token).flatMap { validToken =>
        val fileOp = FileOperation(filePath, op, validToken.userId)
        FileAccessControl.authorize(validToken, fileOp).map { authorizedOp =>
          executeOperation(authorizedOp)
        }
      }
    }
  }

  private def parseToken(raw: String): Either[String, ServiceToken] = {
    Try {
      val parts = raw.split("\\|")
      require(parts.length == 5, "Invalid token format")
      ServiceToken(parts(0), parts(1), parts(2), parts(3).toLong, parts(4))
    } match {
      case Success(t) => Right(t)
      case Failure(e) => Left(s"Token parse error: ${e.getMessage}")
    }
  }

  private def executeOperation(op: FileOperation): String = {
    s"Executed ${op.operation} on ${op.path} for user ${op.userId}"
  }
}
